package proto_test
import (
 "testing"
 oldproto "github.com/golang/protobuf/proto"
 "google.golang.org/grpc/encoding"
 _ "google.golang.org/grpc/encoding/proto"
)
type legacy struct { Text string `protobuf:"bytes,1,opt,name=text,proto3"` }
func (m *legacy) Reset() { *m = legacy{} }
func (m *legacy) String() string { return m.Text }
func (*legacy) ProtoMessage() {}
func TestReviewLegacy(t *testing.T) {
 m := &legacy{Text:"hello"}
 b, err := oldproto.Marshal(m); if err != nil { t.Fatal(err) }
 c := encoding.GetCodec("proto")
 if _, err := c.Marshal(m); err != nil { t.Errorf("Marshal legacy: %v", err) }
 if err := c.Unmarshal(b, &legacy{}); err != nil { t.Errorf("Unmarshal legacy: %v", err) }
}
EOF
cat > ../clone-work/legacy_status_test.go <<'EOF'
package status_test
import (
 "testing"
 oldproto "github.com/golang/protobuf/proto"
 "github.com/golang/protobuf/ptypes"
 "google.golang.org/grpc/status"
 "google.golang.org/grpc/codes"
)
type legacy struct { Text string `protobuf:"bytes,1,opt,name=text,proto3"` }
func (m *legacy) Reset() { *m = legacy{} }
func (m *legacy) String() string { return m.Text }
func (*legacy) ProtoMessage() {}
func TestReviewLegacy(t *testing.T) {
 oldproto.RegisterType((*legacy)(nil), "review.Legacy")
 s, err := status.New(codes.Internal,"test").WithDetails(&legacy{Text:"hello"}); if err != nil { t.Fatal(err) }
 var old ptypes.DynamicAny
 if err := ptypes.UnmarshalAny(s.Proto().Details[0], &old); err != nil { t.Fatal(err) }
 if _, ok := old.Message.(*legacy); !ok { t.Fatalf("old got %T",old.Message) }
 if d := s.Details()[0]; true { if _, ok := d.(*legacy); !ok { t.Errorf("Details got %T, want *legacy",d) } }
}
EOF
